from pymongo.errors import ConfigurationError
from .config import DOCUMENTDB_URI, DATABASE_NAME

_client = None
_db = None

def get_client():
    global _client
    if _client is None:
        if not DOCUMENTDB_URI:
            raise ConfigurationError("DOCUMENTDB_URI environment variable is not set")
        # Use a process-wide singleton client (driver best-practice)
        _client = MongoClient(DOCUMENTDB_URI)
    return _client


def get_db():
    global _db
    if _db is None:
        client = get_client()
        _db = client[DATABASE_NAME]
    return _db
"}

{"path": "sample/utils.py", "content": "import hashlib
import math
import numpy as np


def deterministic_scores_from_text(text):
    # Produce deterministic pseudo-random 1-10 scores from text using SHA256
    h = hashlib.sha256(text.encode("utf-8")).digest()
    # split into 3 2-byte chunks
    nums = [int.from_bytes(h[i:i+2], "big") for i in (0,2,4)]
    scores = [1 + (n % 10) for n in nums]
    rationales = [f"Heuristic rationale based on text hash fragment {i}" for i in range(3)]
    return scores, rationales


def deterministic_embedding(text, dims=1536):
    # Create a deterministic "embedding" vector from hash bytes and normalize
    h = hashlib.sha256(text.encode("utf-8")).digest()
    arr = np.frombuffer(h, dtype=np.uint8).astype(float)
    # expand or tile to dims
    if arr.size < dims:
        repeats = math.ceil(dims / arr.size)
        arr = np.tile(arr, repeats)[:dims]
    else:
        arr = arr[:dims]
    vec = arr / (np.linalg.norm(arr) + 1e-12)
    return vec.tolist()


def normalize_embedding(vec):
    a = np.array(vec, dtype=float)
    n = np.linalg.norm(a)
    if n == 0:
        return vec
    return (a / n).tolist()
"}

{"path": "sample/aggregate.py", "content": """"Run aggregation pipeline to compute composite ESG score and rank companies.

Run as: python -m sample.aggregate
"""
from .db import get_db
from .config import COLLECTION_NAME


def aggregate_top(n=10):
    db = get_db()
    col = db[COLLECTION_NAME]
    pipeline = [
        {"$match": {"score_E": {"$exists": True}, "score_S": {"$exists": True}, "score_G": {"$exists": True}}},
        {"$addFields": {"composite": {"$avg": ["$score_E", "$score_S", "$score_G"]}}},
        {"$sort": {"composite": -1}},
        {"$limit": n},
        {"$project": {"name": 1, "score_E": 1, "score_S": 1, "score_G": 1, "composite": 1}}
    ]
    return list(col.aggregate(pipeline))


if __name__ == "__main__":
    top = aggregate_top(20)
    print("Top companies by composite ESG score:")
    for doc in top:
        print(f"{doc['name']}: E={doc['score_E']} S={doc['score_S']} G={doc['score_G']} composite={doc['composite']:.2f}")
"}

